python3 - <<'PY'
import subprocess, re
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits=set()
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x1f%B%x1e', f'origin/friend/{b}'], text=True)
    for chunk in out.split('\x1e'):
        if not chunk.strip(): continue
        sha, body = chunk.split('\x1f',1)
        if 'Friend-Message: 1' in body:
            commits.add(sha.strip())
# transcript sources
import glob, os
src=set()
for root,_,files in os.walk('/tmp/friends-main-wt'):
    for f in files:
        if re.match(r'S\d+/E\d+\.md', f'{os.path.relpath(root,"/tmp/friends-main-wt")}/{f}'.lstrip('./')):
            p=os.path.join(root,f)
            text=open(p).read()
            for m in re.finditer(r'Source: friend/\w+ @ ([0-9a-f]{40})', text):
                src.add(m.group(1))
print('friend commits:',len(commits))
print('transcript sources:',len(src))
missing=sorted(commits-src)
extra=sorted(src-commits)
print('missing:',len(missing))
for s in missing: print(s)
print('extra:',len(extra))
for s in extra: print(s)
